components.css:
.ds-btn-primary { font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; font-weight: 700; background: var(--vermilion, #9d3428); color: var(--paper, #f4efe4); border: 1px solid var(--vermilion, #9d3428); border-radius: 6px; padding: 10px 14px; cursor: pointer; transition: transform 0.25s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), box-shadow 0.25s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-primary:hover { transform: translateY(-1px); box-shadow: 0 8px 16px rgba(36, 30, 22, 0.12); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }
.ds-btn-primary:disabled { opacity: 0.55; cursor: not-allowed; transform: none; box-shadow: none; }
@media (prefers-reduced-motion: reduce) { .ds-btn-primary:hover { transform: none; } }

.ds-btn-secondary { font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; font-weight: 700; background: transparent; color: var(--ink, #241e16); border: 1px solid var(--line-strong, rgba(36, 30, 22, 0.28)); border-radius: 6px; padding: 10px 14px; cursor: pointer; box-shadow: none; transition: transform 0.25s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), box-shadow 0.25s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-btn-secondary:hover { transform: translateY(-1px); box-shadow: 0 8px 16px rgba(36, 30, 22, 0.12); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }
.ds-btn-secondary:disabled { opacity: 0.55; cursor: not-allowed; transform: none; box-shadow: none; }
@media (prefers-reduced-motion: reduce) { .ds-btn-secondary:hover { transform: none; } }

.ds-field { display: grid; gap: 6px; color: var(--ink-soft, #5c5146); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 14px; }
.ds-input { padding: 10px 12px; border-radius: 6px; border: 1px solid var(--line-strong, rgba(36, 30, 22, 0.28)); background: var(--paper, #f4efe4); color: var(--ink, #241e16); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; }
.ds-input::placeholder { color: var(--ink-soft, #5c5146); opacity: 1; }
.ds-input:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }

.ds-mast { background: var(--shelf, #24352f); color: var(--shelf-ink, #f4efe4); }
.ds-mast-inner { max-width: 1120px; margin: 0 auto; padding: 18px 24px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.ds-wordmark { font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-weight: 600; font-size: 1.25rem; letter-spacing: -0.03em; line-height: 1.15; color: var(--shelf-ink, #f4efe4); text-decoration: none; }
.ds-nav-links, .ds-nav-actions { display: flex; align-items: center; gap: 18px; }
.ds-nav-links a, .ds-nav-actions a { color: var(--shelf-muted, #d9d0c0); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; font-weight: 500; text-decoration: none; }
.ds-nav-links a:hover, .ds-nav-actions a:hover { color: var(--shelf-ink, #f4efe4); }
.ds-nav-links a:focus-visible, .ds-nav-actions a:focus-visible, .ds-wordmark:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }

.ds-row { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 16px 18px; border-radius: 8px; border: 1px solid var(--line, rgba(36, 30, 22, 0.14)); background: var(--paper-raised, #fbf7ef); box-shadow: 0 8px 16px rgba(36, 30, 22, 0.04); color: var(--ink, #241e16); text-decoration: none; transition: transform 0.35s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)), box-shadow 0.35s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-row:hover, .ds-row:focus-visible { transform: translateY(-3px); box-shadow: var(--shadow-lift, 0 18px 32px rgba(36, 30, 22, 0.12)); }
.ds-row:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }
.ds-cover { position: relative; width: 58px; height: 84px; flex-shrink: 0; }
.ds-leaf { position: absolute; inset: 0; border-radius: 3px; background: #efe4d0; box-shadow: 2px 4px 8px rgba(36, 30, 22, 0.18); transform-origin: bottom center; transition: transform 0.45s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); display: grid; place-items: center; }
.ds-leaf:nth-child(1) { z-index: 1; transform: rotate(-11deg) translateX(-4px); background: #e7dcc8; }
.ds-leaf:nth-child(2) { z-index: 2; transform: rotate(-5deg) translateX(-2px); }
.ds-leaf:nth-child(3) { z-index: 3; transform: rotate(0); }
.ds-row:hover .ds-leaf:nth-child(1), .ds-row:focus-visible .ds-leaf:nth-child(1) { transform: rotate(-16deg) translate(-8px, -2px); }
.ds-row:hover .ds-leaf:nth-child(2), .ds-row:focus-visible .ds-leaf:nth-child(2) { transform: rotate(-8deg) translate(-3px, -1px); }
.ds-mono { font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-size: 1.7rem; color: var(--shelf, #24352f); }
.ds-main { display: grid; gap: 4px; min-width: 0; }
.ds-title { position: relative; width: fit-content; max-width: 100%; font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-size: 1.2rem; font-weight: 600; letter-spacing: -0.02em; line-height: 1.2; }
.ds-title::after { content: ""; position: absolute; left: 0; bottom: -3px; height: 1px; width: 100%; background: var(--vermilion, #9d3428); transform: scaleX(0); transform-origin: left center; transition: transform 0.45s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
.ds-row:hover .ds-title::after, .ds-row:focus-visible .ds-title::after { transform: scaleX(1); }
.ds-sub, .ds-count { color: var(--ink-soft, #5c5146); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 14px; }
.ds-count { font-weight: 500; }
@media (prefers-reduced-motion: reduce) {
  .ds-row:hover, .ds-row:focus-visible { transform: none; }
  .ds-row:hover .ds-leaf:nth-child(1), .ds-row:focus-visible .ds-leaf:nth-child(1) { transform: rotate(-11deg) translateX(-4px); }
  .ds-row:hover .ds-leaf:nth-child(2), .ds-row:focus-visible .ds-leaf:nth-child(2) { transform: rotate(-5deg) translateX(-2px); }
}

.ds-stamps { display: flex; flex-wrap: wrap; gap: 8px; }
.ds-stamp { display: inline-flex; align-items: center; gap: 8px; padding: 4px 8px; border-radius: 2px; border: 1px solid currentColor; background: transparent; color: var(--ink-soft, #5c5146); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 12px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; }
.ds-dot { width: 8px; height: 8px; border-radius: 999px; background: #b7ab9a; }
.ds-stamp-progress { color: var(--vermilion, #9d3428); background: var(--vermilion-wash, #f6e4df); border-color: rgba(157, 52, 40, 0.35); }
.ds-stamp-progress .ds-dot { background: var(--vermilion, #9d3428); }
.ds-stamp-read { color: var(--moss, #2c5c40); background: var(--moss-wash, #e5efe8); border-color: rgba(44, 92, 64, 0.3); }
.ds-stamp-read .ds-dot { background: var(--moss, #2c5c40); }

.ds-course { background: #fbf3ea; border: 1px solid var(--line, rgba(36, 30, 22, 0.14)); border-radius: 8px; padding: 24px; display: flex; flex-direction: column; gap: 20px; box-shadow: 0 8px 16px rgba(36, 30, 22, 0.04); color: var(--ink, #241e16); }
.ds-course[data-state="read"] { background: var(--moss-wash, #e5efe8); }
.ds-course-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; }
.ds-course-title { margin: 0; font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-size: 1.5rem; font-weight: 600; letter-spacing: -0.02em; }
.ds-stamp { display: inline-flex; align-items: center; gap: 8px; padding: 4px 8px; border-radius: 2px; border: 1px solid currentColor; font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 12px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; white-space: nowrap; }
.ds-stamp-progress { color: var(--vermilion, #9d3428); background: var(--vermilion-wash, #f6e4df); border-color: rgba(157, 52, 40, 0.35); }
.ds-dot { width: 8px; height: 8px; border-radius: 999px; background: var(--vermilion, #9d3428); }
.ds-bar { height: 4px; background: rgba(36, 30, 22, 0.1); overflow: hidden; }
.ds-bar span { display: block; height: 100%; width: 42%; background: var(--vermilion, #9d3428); }
.ds-course[data-state="read"] .ds-bar span { background: var(--moss, #2c5c40); }
.ds-stats { font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 14px; color: var(--ink-soft, #5c5146); font-variant-numeric: tabular-nums; }

.ds-guide { display: flex; flex-direction: column; gap: 8px; max-width: 68ch; padding: 18px 0; border-bottom: 1px solid var(--line, rgba(36, 30, 22, 0.14)); background: transparent; color: var(--ink, #241e16); text-decoration: none; }
.ds-guide-title { font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-size: 1.35rem; font-weight: 600; letter-spacing: -0.02em; }
.ds-guide-excerpt { color: var(--ink-soft, #5c5146); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; line-height: 1.5; }
.ds-guide-action { color: var(--vermilion, #9d3428); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-weight: 700; font-size: 14px; }
.ds-guide:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }

.ds-status { background: var(--paper-raised, #fbf7ef); border: 1px solid var(--line, rgba(36, 30, 22, 0.14)); border-radius: 8px; padding: 22px; box-shadow: 0 8px 16px rgba(36, 30, 22, 0.04); color: var(--ink, #241e16); }
.ds-status-title { font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-weight: 600; font-size: clamp(1.7rem, 3vw, 2.15rem); letter-spacing: -0.02em; line-height: 1.15; margin-bottom: 16px; }
.ds-status-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 18px; }
.ds-status-field { display: grid; gap: 8px; font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 14px; color: var(--ink-soft, #5c5146); font-weight: 700; }
.ds-select-wrap { position: relative; }
.ds-select { width: 100%; appearance: none; padding: 10px 36px 10px 12px; border-radius: 6px; border: 1px solid var(--line-strong, rgba(36, 30, 22, 0.28)); background: var(--paper, #f4efe4); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; font-weight: 600; color: var(--ink, #241e16); }
.ds-select:focus-visible, .ds-range:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }
.ds-caret { position: absolute; right: 12px; top: 50%; width: 8px; height: 8px; border-right: 2px solid var(--ink-soft, #5c5146); border-bottom: 2px solid var(--ink-soft, #5c5146); transform: translateY(-55%) rotate(45deg); pointer-events: none; }
.ds-score-label { display: flex; justify-content: space-between; align-items: baseline; }
.ds-score-value { font-size: 12px; font-weight: 700; letter-spacing: 0.06em; color: var(--vermilion, #9d3428); }
.ds-range { --percent: 30%; width: 100%; appearance: none; height: 6px; border-radius: 999px; background: linear-gradient(90deg, var(--vermilion, #9d3428) 0%, var(--vermilion, #9d3428) var(--percent), #e4d9c6 var(--percent), #e4d9c6 100%); }
.ds-range::-webkit-slider-thumb { appearance: none; width: 24px; height: 24px; border-radius: 50%; background: var(--vermilion, #9d3428); border: 2px solid var(--paper, #f4efe4); box-shadow: 0 4px 8px rgba(36, 30, 22, 0.2); }
.ds-range::-moz-range-track { height: 6px; border-radius: 999px; background: #e4d9c6; }
.ds-range::-moz-range-progress { height: 6px; border-radius: 999px; background: var(--vermilion, #9d3428); }
.ds-range::-moz-range-thumb { width: 24px; height: 24px; border-radius: 50%; background: var(--vermilion, #9d3428); border: 2px solid var(--paper, #f4efe4); box-shadow: 0 4px 8px rgba(36, 30, 22, 0.2); }

.ds-stage { background: rgba(36, 30, 22, 0.46); padding: 24px; }
.ds-dialog { width: min(680px, 92vw); border: 1px solid var(--line-strong, rgba(36, 30, 22, 0.28)); border-radius: 12px; padding: 20px; background: var(--paper, #f4efe4); color: var(--ink, #241e16); box-shadow: var(--shadow-lift, 0 18px 32px rgba(36, 30, 22, 0.12)); display: grid; gap: 16px; }
.ds-dialog-title { font-family: var(--serif, "Spectral", "Iowan Old Style", "Palatino Linotype", Palatino, serif); font-size: 1.4rem; font-weight: 600; }
.ds-dialog-sub { margin: 0; color: var(--ink-soft, #5c5146); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 14px; }
.ds-log { padding: 12px; background: var(--paper-raised, #fbf7ef); border: 1px solid var(--line, rgba(36, 30, 22, 0.14)); border-radius: 8px; }
.ds-msg { padding: 10px 12px; border-radius: 8px; background: var(--paper, #f4efe4); border: 1px solid var(--line, rgba(36, 30, 22, 0.14)); font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; line-height: 1.45; }
.ds-msg-user { background: var(--brass-wash, #f3e6cc); border-color: rgba(141, 106, 50, 0.35); }
.ds-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; }
.ds-btn-primary, .ds-btn-secondary { font-family: var(--sans, "Karla", "Avenir Next", "Segoe UI", sans-serif); font-size: 15px; font-weight: 700; border-radius: 6px; padding: 10px 14px; cursor: pointer; }
.ds-btn-primary { background: var(--vermilion, #9d3428); color: var(--paper, #f4efe4); border: 1px solid var(--vermilion, #9d3428); }
.ds-btn-secondary { background: transparent; color: var(--ink, #241e16); border: 1px solid var(--line-strong, rgba(36, 30, 22, 0.28)); }
.ds-btn-primary:focus-visible, .ds-btn-secondary:focus-visible { outline: 2px solid var(--brass, #8d6a32); outline-offset: 3px; }
